function forecast(d){
  const xs=Object.keys(d).map(Number), ys=Object.values(d);
  const n=xs.length;
  const mx=xs.reduce((a,b)=>a+b,0)/n;
  const my=ys.reduce((a,b)=>a+b,0)/n;
  let num=0, den=0;
  for(let i=0;i<n;i++){ num+=(xs[i]-mx)*(ys[i]-my); den+=(xs[i]-mx)**2; }
  const a=num/den, b=my-a*mx;
  return a*(Math.max(...xs)+1)+b;
}
console.log(forecast({1962:23,1963:20,1964:19,1965:16,1966:3,1967:8}));
